await runScript(async ({ bot, sdk }) => {
let start=Date.now(), last=Date.now(), burns=0, chops=0;
while(Date.now()-start<15*60*1000){
  try{
    const inv=sdk.getInventory();
    const logs=inv.filter((i:any)=>/logs$/i.test(i.name));
    if(logs.length){
      // burn one raw
      const tb=inv.find((i:any)=>/tinderbox/i.test(i.name));
      const before=sdk.getSkill("Firemaking").experience;
      await sdk.sendUseItemOnItem(tb.slot, logs[0].slot);
      burns++;
      try{ await sdk.waitForCondition((s:any)=> (s.skills.find((x:any)=>x.name==='Firemaking')?.experience||0)>before, 3000);}catch{ try{const p=sdk.getState().player; await bot.walkTo(p.worldX+1,p.worldZ);}catch{} }
      try{await bot.dismissBlockingUI();}catch{}
    } else {
      // always normal trees at Lumbridge - reliable
      let r=await bot.chopTree(/^tree$/i as any);
      if(r.success) chops++;
    }
    if(Date.now()-last>4000){ const fm=sdk.getSkill("Firemaking"); const wc=sdk.getSkill("Woodcutting"); console.log(`FM ${fm.level}/${fm.experience} WC ${wc.level}/${wc.experience} chops=${chops} burns=${burns}`); last=Date.now(); }
  }catch(e:any){ console.log("err",e?.message); await new Promise(r=>setTimeout(r,200)); }
}
}, { disconnectAfter: false });

